sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.hotel-footer {
    background: #162a22;
    color: #faf6ef;
    padding: 55px 7% 20px;
    font-family: Arial, sans-serif;
}

.footer-main {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    gap: 40px;
    padding-bottom: 40px;
}

.footer-brand h2 {
    color: #e6c79c;
    font-family: Georgia, serif;
    font-size: 27px;
    margin: 0 0 12px;
}

.footer-brand p {
    color: rgba(250, 246, 239, 0.65);
    font-size: 13px;
    line-height: 1.7;
    max-width: 300px;
}

.footer-links {
    display: flex;
    flex-direction: column;
    gap: 13px;
}

.footer-links h4 {
    color: #e6c79c;
    font-size: 11px;
    letter-spacing: 2px;
    margin: 5px 0 8px;
}

.footer-links a {
    color: rgba(250, 246, 239, 0.75) !important;
    text-decoration: none !important;
    font-size: 13px;
}

.footer-links a:hover {
    color: #e6c79c !important;
}

.footer-bottom {
    border-top: 1px solid rgba(250, 246, 239, 0.15);
    padding-top: 20px;
    display: flex;
    justify-content: space-between;
    gap: 15px;
    color: rgba(250, 246, 239, 0.55);
    font-size: 11px;
}

@media (max-width: 767px) {
    .footer-main {
        grid-template-columns: 1fr;
        gap: 30px;
    }

    .footer-bottom {
        flex-direction: column;
        line-height: 1.6;
    }
}
